-- Couleurs de repli (si matugen n'a pas encore tourné)
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

col_active = "rgba(5cffe7ff)"
col_active2 = "rgba(cba6f7ff)"
col_inactive = "rgba(2a3036ff)"

-- Palette Matugen (écrase les replis si présent)
-- Ces fichiers restent au format "$nom = valeur" : ils sont écrits par matugen et rice/Themes.qml
local function load_colors(path)
    local f = io.open(path, "r")
    if not f then return end
    for line in f:lines() do
        local name, value = line:match("^%$([%w_]+)%s*=%s*(%S+)")
        if name == "col_active" then col_active = value
        elseif name == "col_active2" then col_active2 = value
        elseif name == "col_inactive" then col_inactive = value end
    end
    f:close()
end
load_colors(HOME .. "/.cache/matugen/hypr-colors.conf")
load_colors(HOME .. "/.cache/matugen/catalyst-accent.conf")

